import{_ as l,a0 as t,w as d,s as o,ao as c,I as p,x as a,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"使用位字段和掩码写一个国际象棋游戏 | LCTT x X-CMD","titleTemplate":false,"description":"使用位字段和掩码写一个国际象棋游戏 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用位字段和掩码写一个国际象棋游戏 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用位字段和掩码写一个国际象棋游戏 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20210823 Write a chess game using bit-fields and masks","title":"使用位字段和掩码写一个国际象棋游戏","tag":"202208","desc":""},"relativePath":"202208/20210823 Write a chess game using bit-fields and masks.md","filePath":"[post].md"}'),r={name:"202208/20210823 Write a chess game using bit-fields and masks.md"};function h(g,s,k,b,u,f){const n=t("Link");return d(),o("div",null,[s[15]||(s[15]=c(`<h1 id="使用位字段和掩码写一个国际象棋游戏" tabindex="-1">使用位字段和掩码写一个国际象棋游戏 <a class="header-anchor" href="#使用位字段和掩码写一个国际象棋游戏" aria-label="Permalink to “使用位字段和掩码写一个国际象棋游戏”">​</a></h1><blockquote><p>使用位字段和掩码是不用数据结构组合数据的常用方法。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202208/10/114605qzfzztj2uupb7zuw.jpg" alt=""></p><p>假设你在用 C 语言写一个国际象棋游戏。追踪棋盘上棋子的一种方法是定义一个结构，该结构定义了棋盘上每个可能的棋子及其颜色，因此每个格子都包含该结构中的一个元素。例如，你可以将结构定义成下面这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>struct chess_pc {</span></span>
<span class="line"><span>   int piece;</span></span>
<span class="line"><span>   int is_black;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>有了这个数据结构，你的程序就会知道每个格子里是什么棋子及棋子的颜色。你可以快速识别出棋子是兵、车、马、象、后还是王，以及棋子是黑还是白。但是，有一种更直接的方法来跟踪这些信息，同时只用更少的数据和内存。与为棋盘上的每个方格存储两个 <code>int</code> 值的结构不同，我们可以存储单个 <code>int</code> 值，并使用二进制位字段和掩码来标识每个方格中的棋子和颜色。</p><h3 id="比特和二进制" tabindex="-1">比特和二进制 <a class="header-anchor" href="#比特和二进制" aria-label="Permalink to “比特和二进制”">​</a></h3><p>当使用位字段表示数据时，我们最好像计算机一样思考。让我们从列出可能的棋子开始，并为每个棋子分配一个数字。让我们进入下一个步骤，用二进制表示这个数字，也就是按照计算机追踪它的方式。记住，二进制数是由比特组成的，比特要么是 0，要么是 1。</p><ul><li><code>00000000:</code> 空（0）</li><li><code>00000001:</code> 兵（1）</li><li><code>00000010:</code> 车（2）</li><li><code>00000011:</code> 马（3）</li><li><code>00000100:</code> 象（4）</li><li><code>00000101:</code> 后（5）</li><li><code>00000110:</code> 王（6）</li></ul><p>要列出一个棋盘上的所有棋子，我们只需要三个比特从右到左依次代表值 1、2 和 4。例如，数字 6 是二进制的 110。6 的二进制表示中的其他所有位都是 0。</p><p>一个聪明一点的方法：我们可以使用那些额外的总是为零的比特来跟踪一个棋子是黑还是白。我们可以使用数字 8（二进制 <code>00001000</code>）来表示棋子是否为黑色。如果这一位是 1，则代表该棋子是黑色；如果是 0，则代表该棋子是白色。这被称为<strong>位字段</strong>，稍后我们可以使用二进制<strong>掩码</strong>将其取出。</p><h3 id="用位字段存储数据" tabindex="-1">用位字段存储数据 <a class="header-anchor" href="#用位字段存储数据" aria-label="Permalink to “用位字段存储数据”">​</a></h3><p>要编写一个使用位字段和掩码的国际象棋程序，我们可以从以下定义开始：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/* 棋子 */</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#define EMPTY 0</span><span>   // 空</span></span>
<span class="line"><span>#define PAWN 1</span><span>    // 兵</span></span>
<span class="line"><span>#define ROOK 2</span><span>    // 车</span></span>
<span class="line"><span>#define KNIGHT 3</span><span>  // 马</span></span>
<span class="line"><span>#define BISHOP 4</span><span>  // 象</span></span>
<span class="line"><span>#define QUEEN 5</span><span>   // 后</span></span>
<span class="line"><span>#define KING 6</span><span>    // 王</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/* 棋色 */</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#define BLACK 8</span><span>   // 黑</span></span>
<span class="line"><span>#define WHITE 0</span><span>   // 白</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/* 掩码 */</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#define PIECE 7</span></span></code></pre></div><p>当你为一个棋格赋值时，比如初始化棋盘，你可以赋一个 <code>int</code> 类型的值来跟踪棋子及其颜色。例如，要在棋盘的 <code>0,0</code> 位置存储棋子黑车，你可以使用下面的代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  int board[8][8];</span></span>
<span class="line"><span>..</span></span>
<span class="line"><span>  board[0][0] = BLACK | ROOK;</span></span></code></pre></div><p><code>|</code> 是二进制“或”（<code>OR</code>）操作符，这意味着计算机将合并两个数字的比特。对于每个比特的位置，如果<strong>任意一个</strong>数字的比特为 1，该位置比特的结果也是 1。<code>BLACK</code> 的值（8，即二进制下的 <code>00001000</code>）和 <code>ROOK</code> 的值（2，即二进制下的 <code>00000010</code>）的二进制或结果是二进制下的 <code>00001010</code>，即 10：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    00001000 = 8</span></span>
<span class="line"><span> OR 00000010 = 2</span></span>
<span class="line"><span>    ________</span></span>
<span class="line"><span>    00001010 = 10</span></span></code></pre></div><p>类似地，要在棋盘的 <code>6,0</code> 位置存储一个白色兵，你可以这样做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  board[6][0] = WHITE | PAWN;</span></span></code></pre></div><p>这样存储的值就是 <code>WHITE</code>（0）和 <code>PAWN</code>（1）的二进制或的结果，也即是 1。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    00000000 = 0</span></span>
<span class="line"><span> OR 00000001 = 1</span></span>
<span class="line"><span>    ________</span></span>
<span class="line"><span>    00000001 = 1</span></span></code></pre></div><h3 id="用掩码获取数据" tabindex="-1">用掩码获取数据 <a class="header-anchor" href="#用掩码获取数据" aria-label="Permalink to “用掩码获取数据”">​</a></h3><p>在下棋过程中，程序需要知道棋格中的棋子和它的颜色。我们可以使用二进制掩码来分离这部分。</p><p>举个例子，程序可能需要知道棋局中棋盘上特定棋格的内容，例如位于 <code>board[5][3]</code> 的数组元素。这个是什么棋子，是黑的还是白的？为了识别棋子，使用二进制“与”（<code>AND</code>）操作符将元素的值与掩码 <code>PIECE</code> 结合起来：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  int board[8][8];</span></span>
<span class="line"><span>  int piece;</span></span>
<span class="line"><span>..</span></span>
<span class="line"><span>  piece = board[5][3] &amp; PIECE;</span></span></code></pre></div><p>二进制“与”（<code>AND</code>）操作符（<code>&amp;</code>）将两个二进制值结合，这样对于任意位，如果两个数字中的那个位<strong>都是</strong> 1，那么结果也是 1。例如，如果 <code>board[5][3]</code> 的值是 11（二进制下的 <code>00001011</code>），那么 11 和 掩码 <code>PIECE</code>（7，二进制下的 <code>00000111</code>）二进制与的结果为二进制下的 <code>00000011</code>，也即 3。这代表马，马的值是 3。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    00001011 = 11</span></span>
<span class="line"><span>AND 00000111 = 7</span></span>
<span class="line"><span>    ________</span></span>
<span class="line"><span>    00000011 = 3</span></span></code></pre></div><p>解析棋子的颜色是一个简单的事情，只需要将棋子的值与 <code>BLACK</code> 位字段进行二进制与操作。比如，你可以写一个名为 <code>is_black</code> 的函数来确定棋子是黑还是白：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>int</span></span>
<span class="line"><span>is_black(int piece)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  return (piece &amp; BLACK);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>之所以可以这样，是因为 <code>BLACK</code> 的值为 8（二进制下的 <code>00001000</code>）。在 C 语言中，任何非零值都被视为 <code>True</code>，零总是 <code>False</code>。所以如果 <code>5,3</code> 处的棋子是黑色的，则 <code>is_black(board[5][3])</code> 返回 True 值（8）；如果是白色的，则返回 False 值（0）。</p><h3 id="位字段" tabindex="-1">位字段 <a class="header-anchor" href="#位字段" aria-label="Permalink to “位字段”">​</a></h3><p>使用位字段和掩码是不使用结构组合数据的常用方法。它们值得被程序员收藏到“工具包”中。虽然数据结构对于需要跟踪相关数据的有序编程是一种有价值的工具，但是使用单独的元素来跟踪单个的开或闭值（例如棋子的颜色）的效率较低。在这些情况下，可以考虑使用位字段和掩码来更高效地组合数据。</p><hr>`,34)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/21/8/binary-bit-fields-masks"},{default:i(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/21/8/binary-bit-fields-masks",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...s[2]||(s[2]=[a("Jim Hall",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/FYJNEVERFOLLOWS"},{default:i(()=>[...s[4]||(s[4]=[a("FYJNEVERFOLLOWS",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const y=l(r,[["render",h]]);export{_ as __pageData,y as default};
